package cn.kaoyan.assistant;
import java.io.*;import java.util.*;import java.util.zip.*;
public class PlanSheetReaderTest {
 static File sample(boolean evil)throws Exception{File f=File.createTempFile("plan-test-",".xlsx");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(f))){Map<String,String> parts=new LinkedHashMap<>();parts.put("xl/workbook.xml","<workbook xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='计划' r:id='rId3'/></sheets></workbook>");parts.put("xl/_rels/workbook.xml.rels","<Relationships><Relationship Id='rId3' Target='worksheets/sheet2.xml'/></Relationships>");parts.put("xl/sharedStrings.xml","<sst><si><t>日期</t></si><si><t>任务</t></si><si><t>极限练习</t></si></sst>");parts.put("xl/worksheets/sheet2.xml",evil?"<!DOCTYPE x [<!ENTITY e SYSTEM 'file:///etc/passwd'>]><worksheet>&e;</worksheet>":"<worksheet><sheetData><row r='1'><c r='A1' t='s'><v>0</v></c><c r='C1' t='s'><v>1</v></c></row><row r='2'><c r='A2'><v>46321</v></c><c r='B2' t='inlineStr'><is><t>数学</t></is></c><c r='C2' t='s'><v>2</v></c></row></sheetData></worksheet>");for(Map.Entry<String,String> e:parts.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue().getBytes("UTF-8"));z.closeEntry();}}return f;}
 public static void main(String[] args)throws Exception{Class<?> cls;try{cls=Class.forName("cn.kaoyan.assistant.PlanSheetReader");}catch(ClassNotFoundException e){throw new AssertionError("XLSX reader is not implemented");}java.lang.reflect.Method method=cls.getDeclaredMethod("read",File.class);method.setAccessible(true);File f=sample(false);List<List<String>> rows=(List<List<String>>)method.invoke(null,f);f.delete();if(rows.size()!=2||!rows.get(0).get(2).equals("任务")||!rows.get(0).get(1).equals("")||!rows.get(1).get(1).equals("数学"))throw new AssertionError("shared strings, sparse columns or first sheet mapping broken");boolean refused=false;f=sample(true);try{method.invoke(null,f);}catch(java.lang.reflect.InvocationTargetException e){refused=true;}f.delete();if(!refused)throw new AssertionError("XML entity declarations must be refused");System.out.println("XLSX first-sheet, Chinese, sparse-column and entity checks passed");}
}
